  "No ads": "\u0995\u09cb\u09a8\u09cb \u09ac\u09bf\u099c\u09cd\u099e\u09be\u09aa\u09a8 \u09a8\u09c7\u0987",
  "How it works": "\u098f\u099f\u09bf \u0995\u09c0\u09ad\u09be\u09ac\u09c7 \u0995\u09be\u099c \u0995\u09b0\u09c7",
